package cn.zhuatech.procureagent.controller; import cn.zhuatech.procureagent.common.ApiResponse; import cn.zhuatech.procureagent.dto.ProcureAgentDto.*; import cn.zhuatech.procureagent.service.ProcureAgentService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final ProcureAgentService service;public OperationsAdminController(ProcureAgentService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
